const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const S={projects:[],p:null,db:null,selected:[],edge:null,tool:'select',source:null,history:[],future:[],dark:false,save:'Carregando…',storageError:false,tab:'layers',present:false,step:0,reveal:0,laser:true,temporary:false,controls:true,color:'#8965bf',width:3,snap:true,search:'',filter:'all',busy:false};
let saveTimer,toastTimer,controlTimer,gesture=null,space=false,lastPointer={x:400,y:300},writeChain=Promise.resolve(),dirty=false,dragFrame=0;
try{S.dark=localStorage.getItem('lousa-theme')==='dark'}catch{}document.documentElement.classList.toggle('dark',S.dark);
const B=()=>S.p?.boards[S.p.activeBoard]||null;
const selectedNodes=()=>B()?.nodes.filter(n=>S.selected.includes(n.id))||[];
const btn=(a,label,ic='',cls='')=>`<button class="btn ${cls}" data-a="${a}">${ic?icon(ic):''}${label}</button>`;
const ib=(a,ic,label,active=false)=>`<button class="ib ${active?'active':''}" data-a="${a}" title="${label}" aria-label="${label}" ${active?'aria-pressed="true"':''}>${icon(ic)}</button>`;
const toolNames={select:'Selecionar · V',hand:'Mover quadro · H',topic:'Tópico · M',text:'Texto · T',connect:'Conectar tópicos · C',pen:'Caneta · P',highlight:'Marca-texto · J',eraser:'Borracha · E',shape:'Forma geométrica · R',note:'Nota adesiva · N',image:'Inserir imagem · I',audio:'Inserir áudio',formula:'Fórmula matemática',code:'Bloco de código'};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function closeModal(){modal.innerHTML=''}
function dialog(title,body,actions='',wide=false){modal.innerHTML=`<div class="overlay"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="row"><h2>${title}</h2><div class="spacer"></div>${ib('close-modal','close','Fechar')}</div>${body}<div class="actions">${actions}</div></section></div>`;setTimeout(()=>modal.querySelector('input:not([type=color]),textarea,[contenteditable]')?.focus(),30)}
function ask(title,value,callback,label='Nome'){dialog(title,`<div class="field"><label for="ask-input">${label}</label><input id="ask-input" maxlength="160" value="${esc(value)}"></div>`,btn('close-modal','Cancelar')+btn('ask-ok','Salvar','check','primary'));const input=$('#ask-input');input.select();const done=()=>{const v=input.value.trim();if(!v){toast('Escreva um nome para continuar.');return}closeModal();callback(v)};$('#modal [data-a=ask-ok]').onclick=done;input.onkeydown=e=>{if(e.key==='Enter')done()}}
function confirmAction(title,text,callback){dialog(title,`<p>${esc(text)}</p>`,btn('close-modal','Cancelar')+btn('confirm-ok','Confirmar','check','primary'));$('#modal [data-a=confirm-ok]').onclick=()=>{closeModal();callback()}}
function checkpoint(){if(!S.p)return;S.history.push(clone(S.p));if(S.history.length>35)S.history.shift();S.future=[]}
function mutate(fn,render=true){checkpoint();fn();changed();if(render)refresh()}
function changed(){if(!S.p)return;S.p.updated=Date.now();dirty=true;S.save='Alterações pendentes';updateSave();clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist(),450)}
function updateSave(){const el=$('#save-state');if(el)el.innerHTML=`<span class="dot" style="background:${S.storageError?'#dd8c64':dirty?'#c9b06e':'#80a58a'}"></span>${esc(S.save)}`}
async function persist(p=S.p){if(!p)return;const snapshot=clone(p);const i=S.projects.findIndex(x=>x.id===p.id);if(i>=0)S.projects[i]=clone(p);else S.projects.push(clone(p));if(!S.db){S.save='Não salvo · exporte uma cópia';S.storageError=true;updateSave();return}S.save='Salvando…';updateSave();writeChain=writeChain.catch(()=>{}).then(()=>dbWrite(S.db,snapshot));try{await writeChain;if(S.p?.id===snapshot.id&&S.p.updated===snapshot.updated){dirty=false;S.save='Salvo neste navegador';S.storageError=false;updateSave()}}catch(e){S.save='Falha ao salvar · exporte uma cópia';S.storageError=true;updateSave();toast('Não foi possível salvar. Seu trabalho continua aberto. Exporte o projeto para preservá-lo.')}}
async function home(){if(S.present)endPresentation();clearTimeout(saveTimer);await persist();S.p=null;S.selected=[];S.edge=null;S.history=[];S.future=[];renderHome()}
function mini(b){if(!b)return'';return b.nodes.filter(n=>!n.hidden&&n.type!=='audio').map(n=>`<div style="position:absolute;left:${n.x}px;top:${n.y}px;width:${n.w}px;height:${n.h}px;background:${n.fill};color:${n.color};font-size:${n.fontSize}px;font-weight:${n.bold?700:400};border-radius:10px;overflow:hidden;padding:14px;white-space:pre-wrap">${n.type==='image'?`<img src="${esc(n.src)}" style="width:100%;height:100%;object-fit:cover">`:esc(n.type==='formula'?'6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂':plain(n.html)||n.text)}</div>`).join('')}
function brand(){return `<div class="brand"><span class="brand-mark">${icon('pen')}</span>lousa<span style="color:var(--accent)">.</span></div>`}
function renderHome(){app.innerHTML=`<main class="home"><nav class="home-nav">${brand()}<div><div class="eyebrow" style="margin:0 14px 13px">Seu espaço criativo</div><button class="nav-link ${S.filter==='all'?'active':''}" data-a="all-projects">${icon('grid')}Meus projetos</button><button class="nav-link" data-a="show-templates">${icon('spark')}Modelos para começar</button><button class="nav-link" data-a="import">${icon('upload')}Importar projeto</button></div><div class="home-note">${icon('book')}<strong style="display:block;margin:7px 0">Toda grande aula<br>começa com uma ideia.</strong><span class="muted">Seu conteúdo, no seu ritmo.<br>Prepare. Conecte. Compartilhe.</span></div><div class="profile"><div class="avatar">EU</div><div><strong>Meu estúdio</strong><div class="tiny muted">Espaço pessoal · local</div></div><div class="spacer"></div>${ib('theme',S.dark?'sun':'moon','Alternar tema')}</div></nav><section class="home-main"><header class="home-top"><div><div class="eyebrow">ESTÚDIO DE IDEIAS</div><div style="font-size:13px;margin-top:8px">Um bom dia para ensinar algo novo.</div></div><div class="home-search">${icon('search')}<input id="project-search" aria-label="Buscar projetos" placeholder="Encontrar um projeto…" value="${esc(S.search)}"></div></header><section class="hero"><span class="intro-badge">${icon('spark')} IDEIAS GANHAM FORMA AQUI</span><h1>Mais espaço para pensar.<br>Mais liberdade para ensinar.</h1><p>Transforme suas ideias em aulas visuais. Conecte conceitos, explore caminhos e dê vida ao que você sabe.</p>${btn('new-project','Criar projeto','plus','primary')}<div class="hero-art" aria-hidden="true"><svg viewBox="0 0 250 210"><path d="M80 100 C150 100 130 40 210 40M90 110 C150 110 130 160 210 160" stroke="#b7a4d1" stroke-width="3" fill="none"/><circle cx="210" cy="40" r="5" fill="#b7a4d1"/><circle cx="210" cy="160" r="5" fill="#b7a4d1"/></svg><div class="art-card a">Uma boa ideia ${icon('spark')}</div><div class="art-card b">Novas conexões ↗</div><div class="art-card c">Uma aula incrível.</div></div></section><div class="section-title"><h2>Meus projetos <span class="muted" style="font-size:13px;font-weight:400" id="project-count"></span></h2><div class="row">${btn('import','Importar','upload','small')}${ib('sort-projects','sort','Ordenar por nome ou edição')}</div></div><div id="projects" class="projects"></div><div class="section-title" id="templates"><h2>Um ponto de partida</h2><span class="tiny muted">Do rascunho à próxima aula</span></div><div class="templates">${[['mind','Mapa mental','Conecte suas ideias','connect'],['summary','Resumo de aula','Organize o essencial','book'],['timeline','Linha do tempo','Conte uma história','arrow'],['compare','Comparar conceitos','Descubra relações','group']].map(([v,t,d,i])=>`<button class="template" data-template="${v}"><span class="symbol">${icon(i)}</span><strong>${t}</strong><div class="tiny muted" style="margin-top:6px">${d}</div></button>`).join('')}</div><p class="foot-note">${icon('lock')} Seus projetos e mídias ficam neste navegador. Exporte uma cópia para levar seu trabalho com você.</p></section></main>`;renderProjects();$('#project-search').oninput=e=>{S.search=e.target.value;renderProjects()}}
let sortByName=false;
function renderProjects(){const ps=S.projects.filter(p=>p.name.toLocaleLowerCase('pt-BR').includes(S.search.toLocaleLowerCase('pt-BR'))).sort((a,b)=>sortByName?a.name.localeCompare(b.name):b.updated-a.updated);$('#project-count').textContent=`/ ${ps.length}`;$('#projects').innerHTML=ps.length?ps.map(p=>`<article class="project"><div class="project-preview" role="button" tabindex="0" aria-label="Abrir ${esc(p.name)}" data-open="${p.id}"><div class="mini">${mini(p.boards[0])}</div></div><div class="project-info"><div><h3><button data-open="${p.id}" style="text-align:left;padding:0">${esc(p.name)}</button></h3><p>${p.boards.length} quadro${p.boards.length>1?'s':''} · Editado em ${new Date(p.updated).toLocaleDateString('pt-BR',{day:'numeric',month:'short'})}</p></div><button class="ib project-menu-btn" data-project-menu="${p.id}" aria-label="Opções de ${esc(p.name)}">${icon('more')}</button></div></article>`).join(''):`<div class="empty-projects">Nenhum projeto encontrado. Uma nova ideia pode começar agora.</div>`}
async function openProject(id){clearTimeout(saveTimer);if(S.p)await persist();const p=S.projects.find(x=>x.id===id);if(!p)return;S.p=clone(p);S.selected=[];S.edge=null;S.tool='select';S.history=[];S.future=[];S.save=S.db?'Salvo neste navegador':'Sessão sem armazenamento';S.p.activeBoard=Math.min(S.p.activeBoard||0,S.p.boards.length-1);renderEditor();requestAnimationFrame(()=>fitAll(false));}
async function newProject(template='blank',name){const p=project(template,name);S.projects.push(p);await openProject(p.id);changed();}
function renderEditor(){const b=B();if(!b)return;app.innerHTML=`<main class="editor ${S.present?'presenting':''}"><header class="topbar">${ib('home','back','Voltar aos projetos')}${brand()}<div class="divider"></div><div class="title-text"><button class="project-name" data-a="rename-project" title="Renomear projeto">${esc(S.p.name)}</button><span class="saved" id="save-state"></span></div><div class="spacer"></div><div class="top-actions">${ib('undo','undo','Desfazer · Ctrl+Z')}${ib('redo','redo','Refazer · Ctrl+Shift+Z')}<div class="divider"></div><button class="ib theme-btn" data-a="theme" title="Alternar tema" aria-label="Alternar tema">${icon(S.dark?'sun':'moon')}</button>${btn('export','<span>Exportar</span>','download')}${btn('present','<span>Apresentar</span>','play','primary')}</div></header><div class="workspace"><aside class="side" id="sidebar"></aside><section class="board-wrap" data-tool="${S.tool}" id="board-wrap"><div class="viewport" id="viewport" tabindex="0" aria-label="Quadro interativo"><div class="world" id="world"><svg class="edges" id="edges"></svg><svg class="edges" id="strokes"></svg><div id="nodes"></div><svg class="edges" id="annotations"></svg></div></div><div class="canvas-label">QUADRO ${String(S.p.activeBoard+1).padStart(2,'0')}<strong>${esc(b.name)}</strong></div><div class="tool-hint" id="tool-hint"></div><div class="tool-rail" role="toolbar" aria-label="Ferramentas do quadro">${Object.entries(toolNames).map(([t,label],i)=>`${[2,5,8,10].includes(i)?'<span class="sep"></span>':''}<button class="ib ${S.tool===t?'active':''}" data-tool="${t}" aria-label="${label}" title="${label}">${icon(t)}</button>`).join('')}</div><div class="zoom">${ib('zoom-out','minus','Diminuir zoom · −')}<button class="ib percent" data-a="zoom-reset" title="Restaurar zoom" id="zoom-label">100%</button>${ib('zoom-in','plus','Aumentar zoom · +')}<div class="divider" style="height:20px"></div>${ib('fit','fit','Visão geral · 0')}</div><div class="minimap" id="minimap"></div><button class="ib help-float" data-a="help" title="Atalhos e ajuda" aria-label="Atalhos e ajuda">${icon('help')}</button><div class="board-tip">Espaço + arrastar para navegar · Duplo clique para editar</div><div id="present-ui"></div></section><aside class="inspector" id="inspector"></aside></div><footer class="bottom-bar">${ib('toggle-side','menu','Mostrar ou ocultar painéis')}<span id="board-stat"></span><span class="hide-small">·</span><span class="hide-small">${icon('lock')} Armazenamento local</span><div class="spacer"></div><span id="selection-stat"></span><span class="hide-small">Feito para explicar, no seu ritmo.</span>${ib('help','help','Atalhos e ajuda')}</footer></main>`;renderSidebar();renderCanvas();renderInspector();updateSave();updateUndo();setView();bindStage();updateTool();}
function updateUndo(){const a=$('[data-a=undo]'),b=$('[data-a=redo]');if(a)a.disabled=!S.history.length;if(b)b.disabled=!S.future.length}
function refresh(){if(!S.p)return;renderCanvas();renderSidebar();renderInspector();updateUndo();updateSave()}
function nodeHTML(n){const selected=S.selected.includes(n.id)&&!S.present,hidden=S.present&&n.reveal>S.reveal;let content;if(n.type==='image')content=`<img draggable="false" alt="${esc(n.text)}" src="${esc(n.src)}">`;else if(n.type==='audio')content=`<div class="audio-label">${icon('audio')} ${esc(n.text)}</div><audio controls preload="metadata" src="${esc(n.src)}" aria-label="${esc(n.text)}"></audio><div class="audio-extra"><span>Velocidade</span><select data-audio-rate="${n.id}" aria-label="Velocidade do áudio">${[.5,.75,1,1.25,1.5,2].map(v=>`<option value="${v}" ${v===(n.rate||1)?'selected':''}>${v}×</option>`).join('')}</select><label style="margin-left:auto">Volume</label><input data-audio-volume="${n.id}" aria-label="Volume do áudio" type="range" min="0" max="1" step=".05" value="${n.volume??1}" style="width:65px"></div>`;else content=`<div class="node-content" ${n.type==='formula'?'data-formula="true"':''}>${n.type==='formula'?mathHTML(n.text):n.html||esc(n.text)}</div>`;return `<div class="node ${n.type} ${n.shape||''} ${selected?'selected':''} ${n.locked?'locked':''} ${hidden?'revealed-hidden':''}" data-n="${n.id}" style="left:${n.x}px;top:${n.y}px;width:${n.w}px;height:${n.h}px;background:${n.fill};color:${S.dark&&n.fill==='transparent'&&n.color==='#302741'?'#efedf5':n.color};font-family:${n.fontFamily};font-size:${n.fontSize}px;font-weight:${n.bold?700:400};text-align:${n.align};border-radius:${n.type==='note'?'3px':n.type==='text'||n.type==='formula'?'0':'13px'};${n.hidden?'display:none;':''}">${content}${selected&&!n.locked?'<span class="resize" data-resize="true" aria-label="Redimensionar"></span>':''}${n.reveal&&!S.present?`<span class="reveal-badge" title="Revelar na etapa ${n.reveal}">${n.reveal}</span>`:''}</div>`}
function renderCanvas(){
 const b=B(),root=$('#nodes');if(!b||!root)return;
 const existing=new Map([...root.children].map(el=>[el.dataset.n,el]));
 const keep=new Set();
 b.nodes.forEach((n,i)=>{
  const props=[n.type,n.text,n.html,n.src,n.shape,n.fill,n.color,n.fontFamily,n.fontSize,n.bold,n.align,n.rate,n.volume,n.reveal,n.hidden,S.dark];
  let el=existing.get(n.id);
  if(!el||!el._lousaProps||!props.every((p,j)=>p===el._lousaProps[j])){
   const oldAudio=el?.querySelector('audio');
   const shell=document.createElement('div');shell.innerHTML=nodeHTML(n);const fresh=shell.firstElementChild;
   if(oldAudio&&oldAudio.getAttribute('src')===n.src)fresh.querySelector('audio')?.replaceWith(oldAudio);
   el?.replaceWith(fresh);el=fresh;el._lousaProps=props;
  }
  el.className=`node ${n.type} ${n.shape||''} ${S.selected.includes(n.id)&&!S.present?'selected':''} ${n.locked?'locked':''} ${S.present&&n.reveal>S.reveal?'revealed-hidden':''}`;
  Object.assign(el.style,{left:n.x+'px',top:n.y+'px',width:n.w+'px',height:n.h+'px',display:n.hidden?'none':''});
  el.style.setProperty('--node-fill',n.fill);
  const handle=el.querySelector('.resize');
  if(S.selected.includes(n.id)&&!S.present&&!n.locked){if(!handle){const h=document.createElement('span');h.className='resize';h.dataset.resize='true';el.append(h)}}else handle?.remove();
  if(root.children[i]!==el)root.insertBefore(el,root.children[i]||null);
  keep.add(n.id);
  if(n.type==='audio'){const a=el.querySelector('audio');a.volume=n.volume??1;a.playbackRate=n.rate||1;a.onerror=()=>toast('O navegador não conseguiu reproduzir este áudio. Tente MP3, WAV ou OGG.')}
 });
 for(const el of [...root.children])if(!keep.has(el.dataset.n))el.remove();
 renderEdges();renderStrokes();renderMinimap();
 $('#board-stat').textContent=`${S.p.boards.length} quadros · ${b.nodes.length} elementos`;
 $('#selection-stat').textContent=S.selected.length?`${S.selected.length} selecionado${S.selected.length>1?'s':''}`:'';
 $('#selection-stat').className='selection-count';
}
function renderEdges(){const b=B();if(!$('#edges'))return;$('#edges').innerHTML=`<defs><marker id="arrowhead" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto-start-reverse"><path d="M0 0L9 4.5L0 9" fill="context-stroke"/></marker></defs>`+b.edges.map(e=>{const a=b.nodes.find(n=>n.id===e.from),c=b.nodes.find(n=>n.id===e.to);if(!a||!c||a.hidden||c.hidden||S.present&&(a.reveal>S.reveal||c.reveal>S.reveal))return'';const[p,q]=edgePoints(a,c),mid=(p.x+q.x)/2;return `<g data-e="${e.id}"><path class="edge" data-e="${e.id}" d="M${p.x},${p.y}C${mid},${p.y} ${mid},${q.y} ${q.x},${q.y}" stroke="${S.edge===e.id?'#8857c7':e.color}" stroke-width="${S.edge===e.id?3:2}" fill="none" ${e.arrow?'marker-end="url(#arrowhead)"':''}/>${e.label?`<text class="edge-label" data-e="${e.id}" x="${mid}" y="${(p.y+q.y)/2-9}" text-anchor="middle">${esc(e.label)}</text>`:''}</g>`}).join('')}
const pathD=s=>s.points.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' ');
function renderStrokes(){if(!$('#strokes'))return;$('#strokes').innerHTML=B().strokes.map(s=>`<path d="${pathD(s)}" stroke="${s.color}" stroke-width="${s.width}" stroke-linecap="round" stroke-linejoin="round" opacity="${s.highlight?.35:1}" fill="none"/>`).join('')}
function renderMinimap(){if(!$('#minimap'))return;const b=B(),r=bounds(b.nodes.filter(n=>!n.hidden),b.strokes),z=Math.min(115/Math.max(r.w,1),65/Math.max(r.h,1));$('#minimap').innerHTML=`<svg viewBox="0 0 135 83" style="width:100%;height:100%">${b.nodes.filter(n=>!n.hidden).map(n=>`<rect x="${10+(n.x-r.x)*z}" y="${9+(n.y-r.y)*z}" width="${Math.max(2,n.w*z)}" height="${Math.max(2,n.h*z)}" rx="1" fill="${n.fill==='transparent'?'#b5a5ca':n.fill}"/>`).join('')}</svg>`}
function setView(smooth=false){const b=B(),world=$('#world');if(!b||!world)return;world.classList.toggle('smooth',smooth);world.style.transform=`translate(${b.view.x}px,${b.view.y}px) scale(${b.view.z})`;$('#zoom-label').textContent=Math.round(b.view.z*100)+'%';const vp=$('#viewport');vp.style.backgroundSize=`${24*b.view.z}px ${24*b.view.z}px`;vp.style.backgroundPosition=`${b.view.x}px ${b.view.y}px`;if(smooth)setTimeout(()=>world.classList.remove('smooth'),550)}
function fitRect(r,smooth=true,pad=65){const vp=$('#viewport');if(!vp)return;const box=vp.getBoundingClientRect(),z=Math.min(2.5,Math.max(.08,Math.min((box.width-pad*2)/r.w,(box.height-pad*2)/r.h)));B().view={z,x:(box.width-r.w*z)/2-r.x*z,y:(box.height-r.h*z)/2-r.y*z};setView(smooth)}
function fitAll(smooth=true){fitRect(bounds(B().nodes.filter(n=>!n.hidden),B().strokes),smooth,S.present?45:85)}
function zoom(factor,point){const b=B(),vp=$('#viewport').getBoundingClientRect(),px=point?.x??vp.width/2,py=point?.y??vp.height/2,z=Math.max(.08,Math.min(4,b.view.z*factor)),ratio=z/b.view.z;b.view.x=px-(px-b.view.x)*ratio;b.view.y=py-(py-b.view.y)*ratio;b.view.z=z;setView();if(!S.present)changed()}
function renderSidebar(){if(!$('#sidebar'))return;const b=B();$('#sidebar').innerHTML=`<div class="side-head"><span class="eyebrow">Seus quadros <span class="muted">/ ${S.p.boards.length}</span></span>${ib('add-board','plus','Adicionar quadro')}</div><div class="board-list">${S.p.boards.map((q,i)=>`<div class="board-item ${q.id===b.id?'active':''}" data-board="${i}" tabindex="0" role="button" aria-label="Abrir quadro ${esc(q.name)}"><div class="thumb"><div class="mini">${mini(q)}</div></div><div class="board-label"><span class="number">${String(i+1).padStart(2,'0')}</span><span style="flex:1;overflow:hidden;white-space:nowrap;text-overflow:ellipsis">${esc(q.name)}</span><button class="ib board-delete" data-board-menu="${i}" title="Opções do quadro" aria-label="Opções do quadro">${icon('more')}</button></div></div>`).join('')}</div><div class="side-tabs"><button data-tab="layers" class="${S.tab==='layers'?'active':''}">Camadas</button><button data-tab="frames" class="${S.tab==='frames'?'active':''}">Enquadramentos</button></div><div class="layers">${S.tab==='layers'?b.nodes.slice().reverse().map(n=>`<div class="layer-row ${S.selected.includes(n.id)?'active':''}" data-layer="${n.id}">${icon(n.type)}<span>${esc((plain(n.html)||n.text).slice(0,35)||'Elemento')}</span><button class="ib" data-visibility="${n.id}" title="${n.hidden?'Mostrar':'Ocultar'} elemento" aria-label="${n.hidden?'Mostrar':'Ocultar'} elemento">${icon(n.hidden?'hide':'eye')}</button><button class="ib" data-lock="${n.id}" title="${n.locked?'Desbloquear':'Bloquear'} elemento" aria-label="${n.locked?'Desbloquear':'Bloquear'} elemento">${icon(n.locked?'lock':'unlock')}</button></div>`).join(''):frameRows()}</div><div class="side-bottom">${S.tab==='frames'?btn('save-frame','Salvar enquadramento','frame','small'):`${btn('auto-layout','Organizar mapa','spark','small')}<div style="margin-top:8px">Um lugar para cada ideia.</div>`}</div>`}
function allFrames(){return S.p.boards.flatMap((b,bi)=>b.frames.map((f,fi)=>({...f,bi,fi})))}
function frameRows(){const frames=B().frames;return frames.length?frames.map((f,i)=>`<div class="frame-row"><span class="number">${i+1}</span><button class="frame-name" data-frame="${i}">${esc(f.name)}</button><button class="ib" data-frame-up="${i}" title="Mover enquadramento para cima" aria-label="Mover para cima">${icon('up')}</button><button class="ib" data-frame-rename="${i}" title="Renomear enquadramento" aria-label="Renomear enquadramento">${icon('edit')}</button><button class="ib" data-frame-delete="${i}" title="Excluir enquadramento" aria-label="Excluir enquadramento">${icon('trash')}</button></div>`).join(''):`<div class="frame-empty">Enquadre uma área com o zoom e salve aqui. A apresentação seguirá esta sequência, na ordem dos quadros.</div>`}
function renderInspectorContent(){const el=$('#inspector');if(!el)return;const ns=selectedNodes(),n=ns[0],e=B().edges.find(e=>e.id===S.edge);if(e){el.innerHTML=`<h3>Conexão</h3><div class="field"><label for="edge-label">Rótulo</label><input id="edge-label" data-edge-prop="label" value="${esc(e.label)}" maxlength="300"></div><div class="field"><label>Cor</label><input type="color" data-edge-prop="color" value="${e.color}"></div><label><input type="checkbox" data-edge-prop="arrow" ${e.arrow?'checked':''}> Mostrar seta</label><hr>${btn('delete','Excluir conexão','trash','small danger')}`;return}
if(['pen','highlight','eraser'].includes(S.tool)){el.innerHTML=`<h3>${S.tool==='pen'?'Caneta':S.tool==='highlight'?'Marca-texto':'Borracha'}</h3>${S.tool!=='eraser'?`<div class="field"><label>Cor do traço</label><div class="row"><input type="color" id="draw-color" value="${S.color}"><span>${S.color}</span></div></div><div class="field"><label>Espessura · ${S.width} px</label><input id="draw-width" type="range" min="1" max="40" value="${S.width}"></div>`:'<p class="muted" style="line-height:1.8">Clique ou passe a borracha sobre um traço para apagar o desenho inteiro.</p>'}<div class="tip-box">Desenhe com o botão esquerdo. Segure <kbd>Espaço</kbd> para navegar. <kbd>V</kbd> volta à seleção.</div>`;return}
if(!n){el.innerHTML=`<div class="eyebrow">O espaço é seu</div><div class="empty-inspector"><div class="empty-art">${icon('select')}</div><h4>Ideias em movimento</h4>Selecione um elemento<br>para dar o seu toque.</div><div class="tip-box"><strong style="color:var(--ink)">Um atalho para criar</strong><br><kbd>M</kbd> novo tópico<br><kbd>C</kbd> conectar ideias<br><kbd>T</kbd> escrever um texto<br><kbd>P</kbd> desenhar livremente</div><hr><label class="row"><input type="checkbox" id="snap-toggle" ${S.snap?'checked':''}> Alinhar com guias</label><div class="tip-box">${icon('frame')} Pensado para suas aulas.<br>Use enquadramentos 16:9 para organizar a explicação em vídeo.</div>`;return}
const multi=ns.length>1;el.innerHTML=`<div class="side-head"><h3 style="margin:0">${multi?`${ns.length} elementos`:({topic:'Tópico',text:'Texto',note:'Nota adesiva',shape:'Forma',image:'Imagem',audio:'Áudio',formula:'Fórmula',code:'Código'}[n.type])}</h3>${ib('clear-selection','close','Limpar seleção')}</div>${!multi&&!['image','audio','shape'].includes(n.type)?btn('edit','Editar conteúdo','edit','small full'):''}${!multi&&['image','audio'].includes(n.type)?`<div class="field"><label>Descrição</label><input data-prop="text" value="${esc(n.text)}" maxlength="160"></div>`:''}<div class="row"><div class="field"><label>Largura</label><input type="number" data-prop="w" min="35" max="10000" value="${Math.round(n.w)}" ${n.locked?'disabled':''}></div><div class="field"><label>Altura</label><input type="number" data-prop="h" min="25" max="10000" value="${Math.round(n.h)}" ${n.locked?'disabled':''}></div></div>${!['image','audio'].includes(n.type)?`<div class="field"><label>Fonte</label><select data-prop="fontFamily">${['Arial','Georgia','Verdana','Trebuchet MS','Consolas'].map(f=>`<option ${n.fontFamily===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="row"><div class="field"><label>Tamanho</label><input type="number" data-prop="fontSize" min="8" max="180" value="${n.fontSize}"></div><div class="field"><label>Cor do texto</label><input type="color" data-prop="color" value="${n.color}"></div></div><div class="row" style="margin-bottom:16px">${ib('bold','bold','Negrito',n.bold)}${ib('align-left','left','Alinhar à esquerda',n.align==='left')}${ib('align-center','center','Centralizar',n.align==='center')}${ib('align-right','right','Alinhar à direita',n.align==='right')}</div><div class="field"><label>Preenchimento</label><div class="palette">${colors.map(c=>`<button class="swatch ${c===n.fill?'chosen':''}" style="background:${c}" data-fill="${c}" title="Preenchimento ${c}" aria-label="Preenchimento ${c}"></button>`).join('')}<input type="color" data-prop="fill" aria-label="Cor personalizada" value="${n.fill==='transparent'?'#ffffff':n.fill}"></div><button class="btn small" data-fill="transparent">Sem fundo</button></div>`:''}${n.type==='shape'&&!multi?`<div class="field"><label>Geometria</label><select data-prop="shape"><option value="rect" ${n.shape==='rect'?'selected':''}>Retângulo</option><option value="ellipse" ${n.shape==='ellipse'?'selected':''}>Elipse</option><option value="diamond" ${n.shape==='diamond'?'selected':''}>Losango</option></select></div>`:''}${n.type==='image'&&!multi?btn('crop-image','Recortar imagem','crop','small full'):''}<hr><div class="field"><label>Revelar na etapa (0 = sempre visível)</label><input type="number" data-prop="reveal" min="0" max="99" value="${n.reveal||0}"></div><div class="row">${ib('front','up','Avançar uma camada')}${ib('back','down','Recuar uma camada')}${ib('lock-selection',n.locked?'unlock':'lock',n.locked?'Desbloquear':'Bloquear')}${ib('duplicate','copy','Duplicar · Ctrl+D')}${ib('delete','trash','Excluir · Delete')}</div>${multi?`<hr><div class="row">${btn('group','Agrupar','group','small')}${btn('ungroup','Separar','','small')}</div><div class="row" style="margin-top:8px">${btn('align-nodes','Alinhar','align','small')}${btn('distribute','Distribuir','','small')}</div>`:n.group?`<hr>${btn('ungroup','Desagrupar','group','small')}`:''}<div class="tip-box">${n.locked?'Desbloqueie o elemento para editá-lo.':'Arraste para mover. Use o canto para redimensionar. Shift + clique seleciona vários.'}</div>`}
function renderInspector(){renderInspectorContent();if(!["pen","highlight","eraser"].includes(S.tool)&&selectedNodes().length&&selectedNodes().every(n=>n.locked))$("#inspector")?.querySelectorAll("input,select,[data-fill],[data-a=edit],[data-a=crop-image],[data-a=bold],[data-a^=align-]").forEach(el=>el.disabled=true)}
function select(ids,edge=null){S.selected=ids;S.edge=edge;renderCanvas();renderInspector();renderSidebar()}
function updateTool(){if(!$('#board-wrap'))return;$('#board-wrap').dataset.tool=S.tool;document.querySelectorAll('.tool-rail [data-tool]').forEach(e=>e.classList.toggle('active',e.dataset.tool===S.tool));const hints={select:'Selecione, mova e conecte suas ideias',hand:'Arraste para explorar o quadro',connect:S.source?'Agora clique no tópico de destino':'Clique no primeiro tópico para conectar',pen:'Desenhe livremente · Espaço para navegar',highlight:'Destaque suas ideias · Espaço para navegar',eraser:'Passe sobre um traço para apagar'};$('#tool-hint').textContent=hints[S.tool]||'';renderInspector()}
function setTool(t){if(S.present)return;if(['image','audio'].includes(t)){pickMedia(t);return}if(['topic','text','note','shape','formula','code'].includes(t)){addNode(t);return}S.tool=t;S.source=null;updateTool()}
function centerPoint(){const vp=$('#viewport').getBoundingClientRect(),v=B().view;return{x:(vp.width/2-v.x)/v.z,y:(vp.height/2-v.y)/v.z}}
function addNode(type,opts={}){const c=centerPoint();const n=node(type,c.x-120,c.y-55,opts);if(type==='shape'){n.text='';n.fill='#e1eee4'}if(type==='code'){n.w=480;n.h=230;n.fontSize=17}if(type==='formula'){n.w=550;n.h=100;n.fontSize=30}mutate(()=>B().nodes.push(n),false);S.tool='select';S.source=null;select([n.id]);updateTool();updateUndo();if(['text','formula','code'].includes(type))editNode(n)}
function undo(){if(!S.history.length)return;S.future.push(clone(S.p));S.p=S.history.pop();S.selected=[];S.edge=null;changed();renderEditor()}
function redo(){if(!S.future.length)return;S.history.push(clone(S.p));S.p=S.future.pop();S.selected=[];S.edge=null;changed();renderEditor()}
function deleteSelected(){if(S.edge){mutate(()=>B().edges=B().edges.filter(e=>e.id!==S.edge));S.edge=null;renderInspector();return}const ids=selectedNodes().filter(n=>!n.locked).map(n=>n.id);if(!ids.length){toast('Selecione um elemento desbloqueado para excluir.');return}mutate(()=>{B().nodes=B().nodes.filter(n=>!ids.includes(n.id));B().edges=B().edges.filter(e=>!ids.includes(e.from)&&!ids.includes(e.to));S.selected=[]})}
function duplicateSelection(){const ns=selectedNodes();if(!ns.length)return;const ids=new Map(ns.map(n=>[n.id,uid()])),groups=new Map();mutate(()=>{const copies=ns.map(n=>{const c=clone(n);c.id=ids.get(n.id);c.x+=35;c.y+=35;c.locked=false;if(c.group){if(!groups.has(c.group))groups.set(c.group,uid());c.group=groups.get(c.group)}return c});const es=B().edges.filter(e=>ids.has(e.from)&&ids.has(e.to)).map(e=>({...e,id:uid(),from:ids.get(e.from),to:ids.get(e.to)}));B().nodes.push(...copies);B().edges.push(...es);S.selected=copies.map(n=>n.id)})}
function changeProp(prop,value){const ns=selectedNodes();if(!ns.length)return;if(['w','h','fontSize','reveal'].includes(prop)){value=Number(value);if(!Number.isFinite(value)){renderInspector();return}value=Math.min(prop==='fontSize'?180:prop==='reveal'?99:10000,Math.max(prop==='reveal'?0:prop==='fontSize'?8:prop==='w'?35:25,value))}mutate(()=>ns.filter(n=>!n.locked||prop==='locked').forEach(n=>{if(n.type==='image'&&['w','h'].includes(prop)){const ratio=n.w/n.h;prop==='w'?n.h=value/ratio:n.w=value*ratio}n[prop]=value;if(prop==='text')n.html=''}))}
function changeBoard(i){if(!S.p.boards[i]||i===S.p.activeBoard)return;S.p.activeBoard=i;S.selected=[];S.edge=null;S.source=null;renderEditor();changed()}
function boardMenu(i,x,y){context(x,y,[['rename-board','edit','Renomear',()=>ask('Nome do quadro',S.p.boards[i].name,v=>mutate(()=>S.p.boards[i].name=v))],['duplicate-board','copy','Duplicar',()=>mutate(()=>{const c=clone(S.p.boards[i]);c.id=uid();c.name+=' · cópia';S.p.boards.splice(i+1,0,c)})],['up-board','up','Mover para cima',()=>{if(i>0)mutate(()=>{const current=B().id;[S.p.boards[i-1],S.p.boards[i]]=[S.p.boards[i],S.p.boards[i-1]];S.p.activeBoard=S.p.boards.findIndex(b=>b.id===current)})}],['delete-board','trash','Excluir quadro',()=>{if(S.p.boards.length===1){toast('O projeto precisa de pelo menos um quadro.');return}confirmAction('Excluir este quadro?','Esta ação pode ser desfeita com Ctrl+Z.',()=>{mutate(()=>{S.p.boards.splice(i,1);S.p.activeBoard=Math.min(S.p.activeBoard,S.p.boards.length-1);S.selected=[]},false);renderEditor()})}]])}
function context(x,y,items){$('.context')?.remove();const menu=document.createElement('div');menu.className='context';menu.style.left=Math.min(x,innerWidth-215)+'px';menu.style.top=Math.min(y,innerHeight-items.length*38-20)+'px';menu.innerHTML=items.map(([id,ic,label])=>`<button data-context="${id}">${icon(ic)}${esc(label)}</button>`).join('');document.body.append(menu);menu.onclick=e=>{const b=e.target.closest('[data-context]');if(b){const item=items.find(i=>i[0]===b.dataset.context);menu.remove();item?.[3]()}}}
function editNode(n=selectedNodes()[0]){if(!n||n.locked||['image','audio'].includes(n.type))return;const plainMode=['formula','code'].includes(n.type);const body=plainMode?`<p>${n.type==='formula'?'Digite uma fórmula em LaTeX. Ex.: \\frac{a}{b}, x^2, \\sqrt{x}.':'Escreva seu código. A indentação e as quebras de linha serão preservadas.'}</p><textarea class="plain-editor" id="plain-editor" spellcheck="false">${esc(n.text)}</textarea>${n.type==='formula'?'<div id="math-preview" style="padding:20px;overflow:auto"></div>':''}`:`<div class="rich-tools" role="toolbar" aria-label="Formatação do texto"><select id="rich-font" aria-label="Fonte">${['Arial','Georgia','Verdana','Trebuchet MS','Consolas'].map(f=>`<option ${f===n.fontFamily?'selected':''}>${f}</option>`).join('')}</select><select id="rich-size" aria-label="Tamanho do texto">${[1,2,3,4,5,6,7].map((v,i)=>`<option value="${v}" ${v===4?'selected':''}>${[10,13,16,18,24,32,48][i]} px</option>`).join('')}</select>${[['bold','bold','Negrito'],['italic','italic','Itálico'],['underline','underline','Sublinhado'],['insertUnorderedList','list','Lista'],['insertOrderedList','number','Lista numerada'],['justifyLeft','left','À esquerda'],['justifyCenter','center','Centralizar'],['justifyRight','right','À direita']].map(([c,i,t])=>`<button class="ib" data-cmd="${c}" title="${t}" aria-label="${t}">${icon(i)}</button>`).join('')}<input id="rich-color" type="color" value="${n.color}" title="Cor do texto" aria-label="Cor do texto"><button class="ib" data-cmd="hiliteColor" data-value="#fbe6a6" title="Destacar texto" aria-label="Destacar texto">${icon('highlight')}</button></div><div class="rich-editor" id="rich-editor" contenteditable="true" role="textbox" aria-label="Conteúdo do elemento" aria-multiline="true" style="font-family:${n.fontFamily};font-size:${n.fontSize}px;text-align:${n.align}">${n.html||esc(n.text).replace(/\n/g,'<br>')}</div>`;
dialog(n.type==='formula'?'Editar fórmula':n.type==='code'?'Editar código':'Dê forma à sua ideia',body,btn('close-modal','Cancelar')+btn('save-content','Aplicar','check','primary'),true);if(plainMode){const ta=$('#plain-editor');if(n.type==='formula'){const preview=()=>$('#math-preview').innerHTML=mathHTML(ta.value);ta.oninput=preview;preview()}ta.onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();ta.setRangeText('  ',ta.selectionStart,ta.selectionEnd,'end')}}}else{const ed=$('#rich-editor');let range;const saveRange=()=>{const sel=getSelection();if(sel.rangeCount&&ed.contains(sel.anchorNode))range=sel.getRangeAt(0).cloneRange()};ed.onkeyup=saveRange;ed.onmouseup=saveRange;ed.oninput=saveRange;const cmd=(c,v)=>{ed.focus();if(range){const s=getSelection();s.removeAllRanges();s.addRange(range)}document.execCommand(c,false,v);saveRange()};modal.querySelectorAll('[data-cmd]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>cmd(b.dataset.cmd,b.dataset.value)});$('#rich-font').onchange=e=>cmd('fontName',e.target.value);$('#rich-size').onchange=e=>cmd('fontSize',e.target.value);$('#rich-color').oninput=e=>cmd('foreColor',e.target.value);ed.onpaste=e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))}}$('#modal [data-a=save-content]').onclick=()=>{const value=plainMode?$('#plain-editor').value:sanitize($('#rich-editor').innerHTML);if(n.type==='formula'){try{parseMath(value)}catch(e){toast(e.message);return}}mutate(()=>{if(plainMode)n.text=value;else{n.html=value;n.text=plain(value)}});closeModal()}}
function saveFrame(){const r=$('#viewport').getBoundingClientRect(),v=B().view;let w=Math.min(r.width,r.height*16/9)/v.z,h=w*9/16;const rect={x:(r.width/2-v.x)/v.z-w/2,y:(r.height/2-v.y)/v.z-h/2,w,h};ask('Salvar enquadramento',`Cena ${B().frames.length+1}`,name=>mutate(()=>{B().frames.push({id:uid(),name,...rect});S.tab='frames'}))}
function autoLayout(){const b=B(),ns=b.nodes.filter(n=>n.type==='topic'&&!n.locked&&!n.hidden);if(ns.length<2){toast('Crie pelo menos dois tópicos para organizar o mapa.');return}const incoming=new Set(b.edges.map(e=>e.to)),root=ns.find(n=>!incoming.has(n.id))||ns[0],visited=new Set(),columns=new Map(),queue=[[root,0]];while(queue.length){const[n,d]=queue.shift();if(visited.has(n.id))continue;visited.add(n.id);if(!columns.has(d))columns.set(d,[]);columns.get(d).push(n);for(const e of b.edges.filter(e=>e.from===n.id)){const c=ns.find(n=>n.id===e.to);if(c&&!visited.has(c.id))queue.push([c,d+1])}}for(const n of ns)if(!visited.has(n.id)){if(!columns.has(0))columns.set(0,[]);columns.get(0).push(n)}mutate(()=>{let x=80;for(const[d,col]of columns){col.forEach((n,i)=>{n.x=x;n.y=230+i*170});x+=Math.max(...col.map(n=>n.w))+130}});fitAll()}
function alignNodes(distribute=false){const ns=selectedNodes().filter(n=>!n.locked);if(ns.length<2)return;mutate(()=>{if(distribute){ns.sort((a,b)=>a.x-b.x);const start=ns[0].x,end=ns.at(-1).x+ns.at(-1).w,gap=(end-start-ns.reduce((s,n)=>s+n.w,0))/(ns.length-1);let x=start;ns.forEach(n=>{n.x=x;x+=n.w+gap})}else{const y=Math.min(...ns.map(n=>n.y));ns.forEach(n=>n.y=y)}})}
function localPoint(e){const r=$('#viewport').getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
