function bindStage(){const vp=$('#viewport');vp.onpointerdown=onDown;vp.ondblclick=e=>{if(S.present)return;const n=e.target.closest('[data-n]');if(n)editNode(B().nodes.find(x=>x.id===n.dataset.n));else if(!e.target.closest('[data-e]')&&S.tool==='select'){const p=worldPoint(e);addNode('text',{x:p.x,y:p.y})}};vp.oncontextmenu=e=>{e.preventDefault();if(S.present)return;const el=e.target.closest('[data-n]');if(el&&!S.selected.includes(el.dataset.n))select([el.dataset.n]);context(e.clientX,e.clientY,[['edit','edit','Editar conteúdo',()=>editNode()],['duplicate','copy','Duplicar',duplicateSelection],['group','group','Agrupar seleção',()=>act('group')],['lock','lock','Bloquear / desbloquear',()=>act('lock-selection')],['front','up','Trazer para frente',()=>act('front')],['delete','trash','Excluir',deleteSelected]])};vp.onwheel=e=>{e.preventDefault();if(e.ctrlKey||e.metaKey)zoom(Math.exp(-e.deltaY*.004),localPoint(e));else{const v=B().view;v.x-=e.shiftKey?e.deltaY:e.deltaX;v.y-=e.shiftKey?0:e.deltaY;setView();if(!S.present)changed()}},{passive:false};vp.addEventListener('wheel',e=>e.preventDefault(),{passive:false});vp.ondragover=e=>{e.preventDefault();$('#board-wrap').classList.add('drag-over')};vp.ondragleave=()=>$('#board-wrap').classList.remove('drag-over');vp.ondrop=e=>{e.preventDefault();$('#board-wrap').classList.remove('drag-over');if(S.present)return;insertFiles([...e.dataTransfer.files],worldPoint(e))};vp.onpointermove=e=>{lastPointer=worldPoint(e);if(S.present){showControls();const p=localPoint(e),laser=$('#laser');if(laser){laser.style.left=p.x+'px';laser.style.top=p.y+'px';laser.style.display=S.laser?'block':'none'}}}}
