function isEditing(el){return !!el?.closest?.('input,textarea,select,[contenteditable=true],audio')}
async function act(a){if(a==='close-modal'){closeModal();return}if(a==='theme'){S.dark=!S.dark;document.documentElement.classList.toggle('dark',S.dark);try{localStorage.setItem('lousa-theme',S.dark?'dark':'light')}catch{}if(S.p)renderCanvas();return}if(a==='import'){importProject();return}if(a==='new-project'){ask('Uma nova ideia','Meu novo projeto',v=>newProject('blank',v),'Nome do projeto');return}if(a==='help'){help();return}if(a==='all-projects'){S.filter='all';renderHome();return}if(a==='show-templates'){$('#templates')?.scrollIntoView({behavior:'smooth'});return}if(a==='sort-projects'){sortByName=!sortByName;renderProjects();return}if(!S.p)return;switch(a){case'home':await home();break;case'rename-project':ask('Nome do projeto',S.p.name,v=>{mutate(()=>S.p.name=v);$('.project-name').textContent=v});break;case'undo':undo();break;case'redo':redo();break;case'clear-selection':select([]);break;case'edit':editNode();break;case'delete':deleteSelected();break;case'duplicate':duplicateSelection();break;case'lock-selection':{const ns=selectedNodes(),lock=!ns.every(n=>n.locked);mutate(()=>ns.forEach(n=>n.locked=lock));break}case'bold':changeProp('bold',!selectedNodes()[0]?.bold);break;case'align-left':case'align-center':case'align-right':changeProp('align',a.split('-')[1]);break;case'front':case'back':mutate(()=>{const ns=B().nodes;const indices=ns.map((n,i)=>S.selected.includes(n.id)?i:-1).filter(i=>i>=0);if(a==='front')indices.reverse().forEach(i=>{if(i<ns.length-1&&!S.selected.includes(ns[i+1].id))[ns[i],ns[i+1]]=[ns[i+1],ns[i]]});else indices.forEach(i=>{if(i>0&&!S.selected.includes(ns[i-1].id))[ns[i],ns[i-1]]=[ns[i-1],ns[i]]})});break;case'group':if(S.selected.length<2){toast('Selecione dois ou mais elementos para agrupar.');break}mutate(()=>{const id=uid();selectedNodes().filter(n=>!n.locked).forEach(n=>n.group=id)});break;case'ungroup':mutate(()=>{const groups=new Set(selectedNodes().map(n=>n.group).filter(Boolean));B().nodes.filter(n=>groups.has(n.group)&&!n.locked).forEach(n=>delete n.group)});break;case'align-nodes':alignNodes();break;case'distribute':alignNodes(true);break;case'fit':fitAll();break;case'zoom-in':zoom(1.2);break;case'zoom-out':zoom(1/1.2);break;case'zoom-reset':zoom(1/B().view.z);break;case'auto-layout':autoLayout();break;case'add-board':ask('Novo quadro',`Quadro ${S.p.boards.length+1}`,name=>{mutate(()=>{S.p.boards.push(board(name));S.p.activeBoard=S.p.boards.length-1;S.selected=[]},false);renderEditor()});break;case'save-frame':saveFrame();break;case'present':await startPresentation();break;case'end-present':endPresentation();break;case'next-frame':goFrame(S.step+1);break;case'previous-frame':goFrame(S.step-1);break;case'reveal':reveal();break;case'laser':S.laser=!S.laser;presentationUI();break;case'temporary':S.temporary=!S.temporary;presentationUI();break;case'export':exportDialog();break;case'export-project':exportProject(S.p);closeModal();toast('Projeto editável exportado com todas as mídias.');break;case'export-png':await exportVisual('png',false);break;case'export-pdf':await exportVisual('pdf',false);break;case'export-selection-png':await exportVisual('png',true);break;case'export-selection-pdf':await exportVisual('pdf',true);break;case'crop-image':cropImage();break;case'toggle-side':$('.editor').classList.toggle('compact-side');break}}
document.addEventListener('click',e=>{const ctx=e.target.closest('.context');if(ctx)return;$('.context')?.remove();const el=e.target.closest('button,[data-open],[data-board],[data-layer],[data-frame]');if(!el)return;if(el.dataset.a){act(el.dataset.a);return}if(el.dataset.tool){setTool(el.dataset.tool);return}if(el.dataset.open){openProject(el.dataset.open);return}if(el.dataset.template){newProject(el.dataset.template);return}if(el.dataset.projectMenu){const p=S.projects.find(p=>p.id===el.dataset.projectMenu);context(e.clientX,e.clientY,[['open','book','Abrir',()=>openProject(p.id)],['rename','edit','Renomear',()=>ask('Nome do projeto',p.name,async name=>{p.name=name;p.updated=Date.now();if(S.db)try{await dbWrite(S.db,p)}catch{toast('Falha ao salvar o nome.')}renderHome()})],['duplicate','copy','Duplicar',async()=>{const c=clone(p);c.id=uid();c.name+=' · cópia';c.updated=Date.now();S.projects.push(c);if(S.db)try{await dbWrite(S.db,c)}catch{toast('Falha ao salvar a cópia. Abra e exporte para preservá-la.')}renderHome()}],['export','download','Exportar projeto',()=>exportProject(p)],['delete','trash','Excluir',()=>confirmAction('Excluir projeto?',`O projeto “${p.name}” será removido deste navegador. Exporte uma cópia antes de excluir.`,async()=>{try{if(S.db)await dbWrite(S.db,p.id,true);S.projects=S.projects.filter(x=>x.id!==p.id);renderHome()}catch{toast('Não foi possível excluir. O projeto foi preservado.')}})]]);return}if(el.dataset.boardMenu!==undefined){e.stopPropagation();boardMenu(+el.dataset.boardMenu,e.clientX,e.clientY);return}if(el.dataset.board!==undefined){changeBoard(+el.dataset.board);return}if(el.dataset.tab){S.tab=el.dataset.tab;renderSidebar();return}if(el.dataset.lock){const n=B().nodes.find(n=>n.id===el.dataset.lock);mutate(()=>n.locked=!n.locked);return}if(el.dataset.visibility){const n=B().nodes.find(n=>n.id===el.dataset.visibility);mutate(()=>n.hidden=!n.hidden);return}if(el.dataset.layer){const n=B().nodes.find(n=>n.id===el.dataset.layer);select(e.shiftKey?[...new Set([...S.selected,n.id])]:[n.id]);if(!n.hidden)fitRect(n,true,150);return}if(el.dataset.fill){changeProp('fill',el.dataset.fill);return}if(el.dataset.frame!==undefined){fitRect(B().frames[+el.dataset.frame]);return}if(el.dataset.frameUp!==undefined){const i=+el.dataset.frameUp;if(i>0)mutate(()=>[B().frames[i-1],B().frames[i]]=[B().frames[i],B().frames[i-1]]);return}if(el.dataset.frameDelete!==undefined){mutate(()=>B().frames.splice(+el.dataset.frameDelete,1));return}if(el.dataset.frameRename!==undefined){const f=B().frames[+el.dataset.frameRename];ask('Nome do enquadramento',f.name,v=>mutate(()=>f.name=v));return}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.prop){changeProp(el.dataset.prop,el.type==='checkbox'?el.checked:el.value);return}if(el.dataset.edgeProp){const edge=B().edges.find(x=>x.id===S.edge);if(edge)mutate(()=>edge[el.dataset.edgeProp]=el.type==='checkbox'?el.checked:el.value);return}if(el.id==='snap-toggle'){S.snap=el.checked;return}if(el.id==='draw-color'){S.color=el.value;renderInspector();return}if(el.id==='draw-width'){S.width=+el.value;renderInspector();return}if(el.dataset.audioRate||el.dataset.audioVolume){const id=el.dataset.audioRate||el.dataset.audioVolume,n=B().nodes.find(n=>n.id===id),audio=$(`[data-n="${id}"] audio`);if(el.dataset.audioRate){n.rate=+el.value;audio.playbackRate=n.rate}else{n.volume=+el.value;audio.volume=n.volume}changed();return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal.innerHTML){closeModal();return}$('.context')?.remove();if(S.present){endPresentation();return}S.source=null;S.tool='select';if(S.p){select([]);updateTool()}return}if(isEditing(e.target)||modal.innerHTML)return;const ctrl=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(ctrl&&['s','e','z','y','d','g','a'].includes(k))e.preventDefault();if(!S.p)return;if(S.present){if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();goFrame(S.step+1)}else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();goFrame(S.step-1)}else if(k==='r'){if(e.shiftKey){S.reveal=Math.max(0,S.reveal-1);renderCanvas();presentationUI()}else reveal()}else if(k==='l'){S.laser=!S.laser;presentationUI()}else if(k==='p'){S.temporary=!S.temporary;presentationUI()}else if(k==='h'){S.controls=!S.controls;$('#presentation-controls')?.classList.toggle('hidden',!S.controls);clearTimeout(controlTimer)}else if(k==='0')fitAll();else if(['+','='].includes(k))zoom(1.2);else if(k==='-')zoom(1/1.2);return}if(ctrl){if(k==='z'){e.shiftKey?redo():undo()}else if(k==='y')redo();else if(k==='d')duplicateSelection();else if(k==='g')act(e.shiftKey?'ungroup':'group');else if(k==='s'){persist();toast('Salvamento solicitado.')}else if(k==='e')exportDialog();else if(k==='a')select(B().nodes.filter(n=>!n.hidden).map(n=>n.id));return}if(e.key===' '){space=true;e.preventDefault();return}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();return}if(e.key==='F5'){e.preventDefault();startPresentation();return}if(e.key==='Enter'&&S.selected.length===1){editNode();return}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&S.selected.length){e.preventDefault();const d=e.shiftKey?10:1;mutate(()=>selectedNodes().filter(n=>!n.locked).forEach(n=>{n.x+=(e.key==='ArrowRight'?d:e.key==='ArrowLeft'?-d:0);n.y+=(e.key==='ArrowDown'?d:e.key==='ArrowUp'?-d:0)}));return}const keys={v:'select',h:'hand',m:'topic',t:'text',c:'connect',p:'pen',j:'highlight',e:'eraser',r:'shape',n:'note',i:'image'};if(keys[k]){e.preventDefault();setTool(keys[k])}else if(k==='0')fitAll();else if(['+','='].includes(k))zoom(1.2);else if(k==='-')zoom(1/1.2);else if(k==='?')help()});
document.addEventListener('keyup',e=>{if(e.key===' ')space=false});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&dirty)persist()});window.addEventListener('beforeunload',e=>{if(dirty){persist();e.preventDefault();e.returnValue=''}});window.addEventListener('resize',()=>{if(S.present){const f=allFrames()[S.step];f?fitRect(f,false,25):fitAll(false)}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset?.open)openProject(e.target.dataset.open);if(e.key==='Enter'&&e.target.dataset?.board!==undefined)changeBoard(+e.target.dataset.board)});
async function boot(){app.innerHTML=`<div class="loading">${brand()}<p>Preparando seu espaço de ideias…</p></div>`;try{S.db=await openDB();S.db.onversionchange=()=>{S.db.close();S.db=null;S.storageError=true;toast('O armazenamento mudou em outra aba. Exporte seu projeto e recarregue.')};S.projects=await dbAll(S.db);if(!S.projects.length){const p=project('example');await dbWrite(S.db,p);S.projects=[p]}}catch(e){S.storageError=true;S.save='Armazenamento indisponível';S.projects=[project('example')];setTimeout(()=>dialog('Seu navegador não permitiu salvar',`<p>Você pode trabalhar nesta sessão. Para preservar o conteúdo, exporte o projeto editável antes de fechar a página.</p><p>Libere o armazenamento do site nas configurações do navegador e recarregue para ativar o salvamento automático.</p>`,btn('close-modal','Continuar nesta sessão','','primary')),100)}renderHome()}
boot();
